130	func ensureTrailRepoHasTarget(cmd *cobra.Command, hasTarget bool, hint string) error {
131		if trailRepoFlag(cmd) != "" && !hasTarget {
132			return fmt.Errorf("--repo requires an explicit target: %s", hint)
133		}
134		return nil
135	}
136	
137	// trailListOptions are the inputs to runTrailListAll. Keeping them on a
138	// struct avoids a long positional argument list at the two call sites.
139	type trailListOptions struct {
140		Author       string
141		Status       string
142		JSON         bool
143		Limit        int
144		InsecureHTTP bool
145		// Repo is an optional --repo override (forge/owner/repo or a clone URL);
146		// empty means derive the repo from the origin remote.
147		Repo string
148	}
149	
150	func newTrailShowCmd() *cobra.Command {
151		var branch string
152		cmd := &cobra.Command{
153			Use:   "show [<trail>]",
154			Short: "Show a trail",
155			Long: `Show a trail.
156	
157	If <trail> is omitted, shows the trail for the current branch (or --branch).
158	Otherwise, <trail> may be a trail number, id, or branch in the target repo.`,
159			Args: cobra.MaximumNArgs(1),
160			RunE: func(cmd *cobra.Command, args []string) error {
161				selector := ""
162				if len(args) == 1 {
163					selector = args[0]
164				}
165				if selector != "" && trailBranchFlag(cmd) != "" {
166					return errors.New("pass a trail selector or --branch, not both")
167				}
168				if err := ensureTrailRepoHasTarget(cmd, selector != "" || trailBranchFlag(cmd) != "", "pass a trail selector or --branch"); err != nil {
169					return err
170				}
171				return runTrailShow(cmd.Context(), cmd.OutOrStdout(), cmd.ErrOrStderr(), trailInsecureHTTP(cmd), selector, trailRepoFlag(cmd), trailBranchFlag(cmd))
172			},
173		}
174		cmd.Flags().StringVar(&branch, "branch", "", "Show the trail for this branch instead of the current branch; cannot be combined with a trail selector")
175		return cmd
176	}
177	
178	// runTrailShow shows one trail, defaulting to the current branch's trail.
179	func runTrailShow(ctx context.Context, w, errW io.Writer, insecureHTTP bool, selector, repoOverride, branchOverride string) error {
180		return runAuthenticatedTrailAPI(ctx, errW, insecureHTTP, repoOverride, func(ctx context.Context, client *api.Client) error {
181			forge, owner, repo, err := resolveTrailRepoOrRemote(ctx, repoOverride)
182			if err != nil {
183				return err
184			}
185	
186			found, err := resolveTrailBySelector(ctx, client, forge, owner, repo, selector, branchOverride)
187			if err != nil {
188				return err
189			}
190	
191			// Enrich the list result with the detail endpoint, which carries the
192			// rendered description (trail.body_document.text_snapshot) the list
193			// omits, and surface a browser URL. The detail fetch is best-effort:
194			// the core metadata already came from the list, so a detail failure
195			// falls back to the list body with a warning rather than failing.
196			m := found.ToMetadata()
197			webURL := trailDisplayURL(*found, forge, owner, repo)
198			// Seed the description from the list body so a failed (or skipped)
199			// detail fetch still shows something; a successful detail fetch
200			// supersedes it with the richer body_document text below.
201			bodyText := found.Body
202			descriptionLoaded := strings.TrimSpace(found.Body) != ""
203			if found.Number > 0 {
204				if bt, derr := fetchTrailDescription(ctx, client, forge, owner, repo, found.Number); derr == nil {
205					// A successful fetch means we authoritatively consulted the
206					// description, but it only supersedes the seeded list body when
207					// it actually carries text: an older/partial server that omits
208					// body_document returns "" here and must not blank out a list
209					// body that is present.
210					descriptionLoaded = true
211					if strings.TrimSpace(bt) != "" {
212						bodyText = bt
213					}
214				} else {
215					// Best-effort: warn but still render metadata + URL (and the
216					// list body) rather than failing the whole command.
217					fmt.Fprintf(errW, "Warning: could not load trail description: %v\n", derr)
218				}
219			}
220			printTrailDetails(w, m, webURL, trailDescriptionForDisplay(bodyText, descriptionLoaded))
221			return nil
222		})
223	}
224	
225	// resolveTrailBySelector resolves a trail by an optional selector (trail
226	// number, id, or branch). An empty selector falls back to the current branch's
227	// trail. It returns an actionable error (never a nil trail with a nil error)
228	// when nothing matches, so callers can rely on a non-nil result.
229	func resolveTrailBySelector(ctx context.Context, client *api.Client, forge, owner, repo, selector, branchOverride string) (*api.TrailResource, error) {
230		selector = strings.TrimSpace(selector)
231		if selector == "" {
232			branch, err := resolveTrailBranch(ctx, branchOverride)
233			if err != nil {
234				return nil, fmt.Errorf("no trail selector given and current branch is unknown: %w\nhint: run 'entire trail list --status any' or pass a trail number, id, or branch", err)
235			}
236			found, err := findTrailByBranch(ctx, client, forge, owner, repo, branch)
237			if err != nil {
238				return nil, err
239			}
240			if found == nil {
241				return nil, fmt.Errorf("no trail found for current branch %q\nhint: run 'entire trail create' or 'entire trail list --status any'", branch)
242			}
243			return found, nil
244		}
245		found, err := findTrailBySelector(ctx, client, forge, owner, repo, selector)
246		if err != nil {
247			return nil, err
248		}
249		if found == nil {
250			return nil, fmt.Errorf("no trail %q found in %s/%s/%s (run 'entire trail list --status any')", selector, forge, owner, repo)
251		}
252		return found, nil
253	}
254	
255	func printTrailDetails(w io.Writer, m *trail.Metadata, webURL, bodyText string) {
256		// Color the same fields as the list view (STATUS/PHASE/AUTHOR); everything
257		// else stays plain. Values are pre-colored, so alignment is unaffected.
258		styles := newStatusStyles(w)
259		status := string(m.Status)
260		if style, ok := trailStatusColor(styles, m.Status); ok {
261			status = styles.render(style, status)
262		}
263		author := m.AuthorLogin()
264		if styles.colorEnabled && author != "" {
265			author = styles.render(styles.cyan, author)
266		}
267	
268		// Field labels and the title line render yellow (matching the list header).
269		label := func(s string) string { return styles.render(styles.yellow, s) }
270	
271		fmt.Fprintf(w, "%s\n", styles.render(styles.yellow, "Trail: "+m.Title))
272		if m.Number > 0 {
273			fmt.Fprintf(w, "  %s%d\n", label("Number:  "), m.Number)
274		}
275		if !m.TrailID.IsEmpty() {
276			fmt.Fprintf(w, "  %s%s\n", label("ID:      "), m.TrailID)
277		}
