1460	// splitTrailUpdate separates a full update into a metadata request and an
1461	// optional body request. The server rejects a body update combined with
1462	// status/title/assignees/reviewers/type/priority (trails.ts:4384), so the two
1463	// must be sent as separate PATCH calls. Labels are exempt server-side, but for
1464	// simplicity they travel in the metadata request too; the only cost is one
1465	// extra PATCH in the rare body+labels-only update, which is harmless. hasMeta
1466	// reports whether the metadata request has any field set.
1467	func splitTrailUpdate(full api.TrailUpdateRequest) (meta api.TrailUpdateRequest, hasMeta bool, bodyReq *api.TrailUpdateRequest) {
1468		if full.Body != nil {
1469			b := *full.Body
1470			bodyReq = &api.TrailUpdateRequest{Body: &b}
1471		}
1472		meta = full
1473		meta.Body = nil
1474		hasMeta = meta.Status != nil || meta.Title != nil || meta.Labels != nil ||
1475			meta.Assignees != nil || meta.RequestedReviewers != nil ||
1476			meta.Type != nil || meta.Priority != nil
1477		return meta, hasMeta, bodyReq
1478	}
