1483		if err != nil {
1484			return fmt.Errorf("failed to update trail: %w", err)
1485		}
1486		defer resp.Body.Close()
1487		if err := checkTrailResponse(resp); err != nil {
1488			return err
1489		}
1490		var updateResp api.TrailUpdateResponse
1491		if err := api.DecodeJSON(resp, &updateResp); err != nil {
1492			return fmt.Errorf("failed to decode update response: %w", err)
1493		}
1494		return nil
1495	}
