            head_sha: updatedRow.head_sha,
            priority: (updatedRow.priority ?? "none") as TrailPriority,
            reviewers: trailReviewersFromRow(updatedRow),
            requested_reviewers: updatedRow.requested_reviewers ?? [],
            comment_count: updatedRow.comment_count,
            unresolved_count: updatedRow.unresolved_count,
            checkpoint_count: checkpointCount,
          }
      return c.json({ trail: updatedTrailInfo })
    } catch (err) {
      if (isGitHubAuthError(err)) {
        return c.json({ error: "GitHub token expired" }, 401)
      }
      // The ws door pre-checks `c.env.EDITOR_RELAY` before ever reaching the
      // relay; this arm instead learns the binding is missing from
      // replaceEditorDocumentViaDo's own throw. Without this branch that
      // throw's status (503, do-client.ts) was discarded here in favor of a
      // blanket 500 — the two doors answering the same missing binding
      // differently.
      if (err instanceof EditorDocumentReplaceError) {
        return c.json({ error: err.message }, err.status as ContentfulStatusCode)
      }
      console.error(`Failed to update trail ${row.number}:`, err)
      recordSpanError(err)
      return c.json({ error: "Failed to update trail" }, 500)
    }
  },
)

